t.script:
$(document).ready(function() {
    let allBooks = [];
    let filteredBooks = [];
    let currentFilter = 'all';
    let currentPage = 1;
    const booksPerPage = 12;

    // Charger les données au démarrage
    loadBooks();

    // Événements de recherche
    $('#searchBtn').click(function() {
        filterBooks();
    });

    $('#searchInput').keypress(function(e) {
        if (e.which == 13) { // Enter key
            filterBooks();
        }
    });

    // Événements de filtres
    $('.filter-btn').click(function() {
        $('.filter-btn').removeClass('active');
        $(this).addClass('active');
        currentFilter = $(this).data('filter');
        filterBooks();
    });

    function loadBooks() {
        showLoading(true);

        $.ajax({
            url: '/api/books/data',
            type: 'POST',
            dataType: 'json',
            data: {},
            success: function(response) {
                if (response.success) {
                    allBooks = response.books;
                    filteredBooks = allBooks;
                    updateStatistics();
                    displayBooks();
                } else {
                    showError('Erreur lors du chargement des livres: ' + response.error);
                }
            },
            error: function(xhr, status, error) {
                showError('Erreur de connexion: ' + error);
            },
            complete: function() {
                showLoading(false);
            }
        });
    }

    function filterBooks() {
        const searchTerm = $('#searchInput').val().toLowerCase();

        filteredBooks = allBooks.filter(function(book) {
            const matchesSearch = !searchTerm || 
                book.name.toLowerCase().includes(searchTerm) ||
                (book.description && book.description.toLowerCase().includes(searchTerm)) ||
                (book.category && book.category.toLowerCase().includes(searchTerm)) ||
                (book.authors && book.authors.some(author => author.toLowerCase().includes(searchTerm)));

            const matchesFilter = currentFilter === 'all' || book.state === currentFilter;

            return matchesSearch && matchesFilter;
        });

        currentPage = 1;
        updateStatistics();
        displayBooks();
    }

    function updateStatistics() {
        const total = allBooks.length;
        const available = allBooks.filter(book => book.state === 'available').length;
        const borrowed = allBooks.filter(book => book.state === 'borrowed').length;
        const lost = allBooks.filter(book => book.state === 'lost').length;

        $('#totalCount').text(total);
        $('#availableCount').text(available);
        $('#borrowedCount').text(borrowed);
        $('#lostCount').text(lost);
    }

    function displayBooks() {
        const startIndex = (currentPage - 1) * booksPerPage;
        const endIndex = startIndex + booksPerPage;
        const booksToShow = filteredBooks.slice(startIndex, endIndex);

        let html = '';

        booksToShow.forEach(function(book) {
            const stateClass = getStateClass(book.state);
            const stateText = getStateText(book.state);
            const authorsText = book.authors && book.authors.length > 0 ? book.authors.join(', ') : 'Auteur inconnu';

            html += `
                <div class="col-md-4 col-lg-3 mb-4">
                    <div class="card book-card" onclick="showBookDetails(${book.id})">
                        <div class="card-body">
                            <span class="badge ${stateClass} state-badge">${stateText}</span>
                            <h5 class="card-title">${escapeHtml(book.name)}</h5>
                            <p class="card-text text-muted">${escapeHtml(authorsText)}</p>
                            ${book.category ? `<p class="card-text"><small class="text-muted">Catégorie: ${escapeHtml(book.category)}</small></p>` : ''}
                            ${book.isbn ? `<p class="card-text"><small class="text-muted">ISBN: ${escapeHtml(book.isbn)}</small></p>` : ''}
                        </div>
                    </div>
                </div>
            `;
        });

        $('#booksContainer').html(html);
        updatePagination();
    }

    function updatePagination() {
        const totalPages = Math.ceil(filteredBooks.length / booksPerPage);
        let paginationHtml = '';

        if (totalPages > 1) {
            // Bouton précédent
            paginationHtml += `
                <li class="page-item ${currentPage === 1 ? 'disabled' : ''}">
                    <a class="page-link" href="#" onclick="changePage(${currentPage - 1})">Précédent</a>
                </li>
            `;

            // Pages
            for (let i = 1; i <= totalPages; i++) {
                if (i === 1 || i === totalPages || (i >= currentPage - 2 && i <= currentPage + 2)) {
                    paginationHtml += `
                        <li class="page-item ${i === currentPage ? 'active' : ''}">
                            <a class="page-link" href="#" onclick="changePage(${i})">${i}</a>
                        </li>
                    `;
                } else if (i === currentPage - 3 || i === currentPage + 3) {
                    paginationHtml += '<li class="page-item disabled"><span class="page-link">...</span></li>';
                }
            }

            // Bouton suivant
            paginationHtml += `
                <li class="page-item ${currentPage === totalPages ? 'disabled' : ''}">
                    <a class="page-link" href="#" onclick="changePage(${currentPage + 1})">Suivant</a>
                </li>
            `;
        }

        $('#pagination').html(paginationHtml);
    }

    function getStateClass(state) {
        switch(state) {
            case 'available': return 'badge-success';
            case 'borrowed': return 'badge-warning';
            case 'lost': return 'badge-danger';
            default: return 'badge-secondary';
        }
    }

    function getStateText(state) {
        switch(state) {
            case 'available': return 'Disponible';
            case 'borrowed': return 'Emprunté';
            case 'lost': return 'Perdu';
            default: return 'Inconnu';
        }
    }

    function escapeHtml(text) {
        const div = document.createElement('div');
        div.textContent = text;
        return div.innerHTML;
    }

    function showLoading(show) {
        if (show) {
            $('#loading').removeClass('d-none');
        } else {
            $('#loading').addClass('d-none');
        }
    }

    function showError(message) {
        $('#booksContainer').html(`
            <div class="col-12 text-center">
                <div class="alert alert-danger">
                    <i class="fa fa-exclamation-triangle"></i> ${escapeHtml(message)}
                </div>
            </div>
        `);
    }

    // Fonctions globales
    window.changePage = function(page) {
        if (page >= 1 && page <= Math.ceil(filteredBooks.length / booksPerPage)) {
            currentPage = page;
            displayBooks();
        }
    };

    window.showBookDetails = function(bookId) {
        const book = allBooks.find(b => b.id === bookId);
        if (book) {
            const authorsText = book.authors && book.authors.length > 0 ? book.authors.join(', ') : 'Auteur inconnu';
            const stateText = getStateText(book.state);

            $('#bookModalTitle').text(book.name);
            $('#bookModalBody').html(`
                <div class="row">
                    <div class="col-md-8">
                        <h5>Informations générales</h5>
                        <p><strong>Titre:</strong> ${escapeHtml(book.name)}</p>
                        <p><strong>Auteurs:</strong> ${escapeHtml(authorsText)}</p>
                        ${book.category ? `<p><strong>Catégorie:</strong> ${escapeHtml(book.category)}</p>` : ''}
                        ${book.publisher ? `<p><strong>Éditeur:</strong> ${escapeHtml(book.publisher)}</p>` : ''}
                        ${book.isbn ? `<p><strong>ISBN:</strong> ${escapeHtml(book.isbn)}</p>` : ''}
                        <p><strong>État:</strong> <span class="badge ${getStateClass(book.state)}">${stateText}</span></p>
                    </div>
                    <div class="col-md-4">
                        <h5>Description</h5>
                        <p>${book.description ? escapeHtml(book.description) : 'Aucune description disponible.'}</p>
                    </div>
                </div>
            `);
            $('#bookModal').modal('show');
        }
    };
});
